                              const activePreOrderCart = getActiveCart();
                              if (activePreOrderCart.length === 0) return toast.warning("Add items to cart first!");
                              if (!preOrderScheduledDate) return toast.warning("Please select a scheduled date!");
                              if (!preOrderScheduledTime) return toast.warning("Please select a scheduled time!");
                              if (!customerName || !customerName.trim() || !customerPhone || !customerPhone.trim()) {
                                return toast.warning("Customer Name and Phone are mandatory!");
                              }

                              const { total } = calculateTotals();
                              const preOrderData = {
                                customer_name: customerName,
                                customer_number: customerPhone,
                                customer_address: customerAddress || '',
                                items: activePreOrderCart.map(i => ({
                                  id: i.id,
                                  name: i.priceLabel ? `${i.product_name} (${i.priceLabel})` : i.product_name,
                                  qty: i.quantity,
                                  price: i.price,
                                  modifiers: i.modifiers || [],
                                  kot_category: i.kot_category || 'Main Kitchen'
                                })),"

